head.script:
if (!location.hash) {
  history.replaceState(history.state, "", "#/" );
}
function goFullscreen() {
  var el = document.documentElement;
  var req = el.requestFullscreen || el.webkitRequestFullscreen || el.mozRequestFullScreen || el.msRequestFullscreen;
  if (req) { req.call(el); }
  var btn = document.getElementById('fsbtn');
  if (btn) btn.classList.add('hidden');
}
// Try to enter fullscreen on first user gesture automatically
function autoFs() {
  goFullscreen();
  document.removeEventListener('click', autoFs);
  document.removeEventListener('touchstart', autoFs);
  document.removeEventListener('keydown', autoFs);
}
document.addEventListener('click', autoFs, { once: true });
document.addEventListener('touchstart', autoFs, { once: true });
document.addEventListener('keydown', autoFs, { once: true });
document.addEventListener('fullscreenchange', function() {
  var btn = document.getElementById('fsbtn');
  if (!btn) return;
  if (document.fullscreenElement) btn.classList.add('hidden');
  else btn.classList.remove('hidden');
});
